@@ -0,0 +1,27 @@
+import { test as base, type CDPSession } from '@playwright/test';
+import { PhaseRecorder } from './harness/phases';
+import { installCollector } from './harness/collector';
+import { resetFixture, type Seeded } from './harness/fixture';
+
+type Fixtures = { phases: PhaseRecorder; cdp: CDPSession; seeded: Seeded };
+export const test = base.extend<Fixtures>({
+  phases: async ({}, use, testInfo) => {
+    const file = testInfo.outputPath('phases.jsonl');
+    try { await use(new PhaseRecorder(file, { flow: 'F02', test: testInfo.title })); }
+    finally { await testInfo.attach('phases', { path: file, contentType: 'application/x-ndjson' }); }
+  },
+  seeded: async ({ phases }, use) => {
+    const fixture = await phases.run('fixture-preparation', () => resetFixture('normal'));
+    try { await use(fixture); }
+    finally { await phases.run('cleanup-fixture', () => fixture.remove()); }
+  },
+  page: async ({ page }, use) => {
+    await page.addInitScript(installCollector);
+    await use(page);
+  },
+  cdp: async ({ page, context }, use) => {
+    const cdp = await context.newCDPSession(page);
+    try { await use(cdp); } finally { await cdp.detach(); }
+  },
+});
+export { expect } from '@playwright/test';
diff --git a/tests/perf/harness/actions.ts b/tests/perf/harness/actions.ts
new file mode 100644
index 00000000..435803df
--- /dev/null
+++ b/tests/perf/harness/actions.ts
@@ -0,0 +1,76 @@
+import type { Page } from '@playwright/test';
+import './collector';
+
+export type Point = [number, number];
+export const line = (from: Point, to: Point, steps: number): Point[] => {
+  if (!Number.isInteger(steps) || steps < 1) throw Error('steps must be a positive integer');
+  return Array.from({ length: steps + 1 }, (_, i) => [
+    from[0] + (to[0] - from[0]) * i / steps, from[1] + (to[1] - from[1]) * i / steps,
+  ]);
+};
+
+export async function cadence(count: number, dispatch: (i: number) => Promise<unknown>, intervalMs = 16) {
+  const lags: number[] = [], start = performance.now();
+  for (let i = 0; i < count; i++) {
+    const due = start + i * intervalMs, wait = due - performance.now();
+    if (wait > 0) await new Promise(resolve => setTimeout(resolve, wait));
+    lags.push(Math.max(0, performance.now() - due));
+    await dispatch(i);
+  }
+  return lags;
+}
+export const paced = (page: Page, points: Point[], intervalMs = 16) =>
+  cadence(points.length, i => page.mouse.move(...points[i]), intervalMs);
+
+export async function act(page: Page, predicate: string, input: () => Promise<unknown>, eventType = 'click') {
+  await page.evaluate(({ predicate, eventType }) => window.__perf.arm(predicate, eventType), { predicate, eventType });
+  try {
+    await input();
+    await page.waitForFunction(() => window.__perf.outcome || window.__perf.error, null, { timeout: 30_000 });
+    return await page.evaluate(() => {
+      const c = window.__perf;
+      if (c.error) throw Error(c.error);
+      const first = c.inputs[0];
+      if (!first || c.inputs.length !== 1 || !c.outcome) throw Error('Expected exactly one triggering input');
+      c.flushTasks();
+      const visibleMs = c.outcome.dom - first.created, settledMs = c.outcome.settled - first.created;
+      if (visibleMs < 0 || settledMs < visibleMs) throw Error('Invalid collector clock/order');
+      const end = c.outcome.settled;
+      return { visibleMs, settledMs, inputs: c.inputs,
+        longTasks: c.longTasks.filter(task => task.start < end && task.start + task.duration > first.created) };
+    });
+  } finally { if (!page.isClosed()) await page.evaluate(() => window.__perf.disarm()); }
+}
+
+export async function gesture(page: Page, input: () => Promise<number[]>) {
+  await page.evaluate(() => window.__perf.recordFrames(true));
+  let dispatchLag: number[];
+  try {
+    dispatchLag = await input();
+    await page.evaluate(() => new Promise<void>(resolve => requestAnimationFrame(() => requestAnimationFrame(() => resolve()))));
+  } finally { if (!page.isClosed()) await page.evaluate(() => window.__perf.recordFrames(false)); }
+  const { frames, longTasks } = await page.evaluate(() => {
+    window.__perf.flushTasks();
+    return { frames: window.__perf.frames, longTasks: window.__perf.longTasks };
+  });
+  const intervals = frames.slice(1).map((time, i) => time - frames[i]).sort((a, b) => a - b);
+  if (!intervals.length || !dispatchLag.length) throw Error('Gesture produced no frame/input samples');
+  const pick = (q: number) => intervals[Math.min(intervals.length - 1, Math.floor(q * intervals.length))];
+  return { frames: intervals.length, p50: pick(.5), p95: pick(.95), max: intervals.at(-1)!,
+    overBudgetMs: intervals.reduce((sum, dt) => sum + Math.max(0, dt - 16.7), 0),
+    dispatchLagMax: Math.max(...dispatchLag), dispatchLag, timestamps: frames, longTasks };
+}
+
+// Wait for stable observable geometry, including camera inertia, outside the score.
+export async function stableCanvas(page: Page, selector: string) {
+  await page.evaluate(() => { delete (window as unknown as { __perfStable?: unknown }).__perfStable; });
+  await page.waitForFunction(selector => {
+    const element = document.querySelector(selector) as HTMLElement | null;
+    if (!element) return false;
+    const key = JSON.stringify([element.getBoundingClientRect().toJSON(), element.style.transform]);
+    const state = window as unknown as { __perfStable?: { key: string; count: number } };
+    state.__perfStable = state.__perfStable?.key === key
+      ? { key, count: state.__perfStable.count + 1 } : { key, count: 1 };
+    return state.__perfStable.count >= 8;
+  }, selector, { polling: 'raf' });
+}
diff --git a/tests/perf/harness/collector.ts b/tests/perf/harness/collector.ts
new file mode 100644
index 00000000..4bb22316
--- /dev/null
+++ b/tests/perf/harness/collector.ts
@@ -0,0 +1,71 @@
+export interface Collector {
+  inputs: { type: string; created: number; received: number }[];
+  longTasks: { start: number; duration: number }[];
+  frames: number[];
+  outcome: { dom: number; settled: number } | null;
+  error: string | null;
+  arm(predicate: string, eventType?: string): void;
+  disarm(): void;
+  recordFrames(enabled: boolean): void;
+  flushTasks(): void;
+}
+declare global { interface Window { __perf: Collector } }
+
+// Self-contained: Playwright serializes this function into the browser.
+export function installCollector() {
+  let actionFrame = 0, gestureFrame = 0;
+  let armed = false, wantedEvent = 'click', actionStart = Infinity;
+  const c: Collector = window.__perf = {
+    inputs: [], longTasks: [], frames: [], outcome: null, error: null,
+    arm(source, eventType = 'click') {
+      c.inputs = []; c.longTasks = [];
+      c.disarm();
+      observer?.takeRecords(); // discard queued entries from the preceding action
+      c.outcome = null; c.error = null;
+      wantedEvent = eventType; armed = true; actionStart = performance.now();
+      const predicate = new Function(`return (${source})`)() as () => unknown;
+      let dom = 0, fingerprint = '', stableFrames = 0;
+      const check = () => {
+        try {
+          // In particular, never satisfy the release predicate before pointerup.
+          if (c.inputs.length) {
+            const result = predicate();
+            if (result) {
+              const current = JSON.stringify(result);
+              if (!dom) dom = performance.now();
+              stableFrames = current === fingerprint ? stableFrames + 1 : 1;
+              fingerprint = current;
+              if (stableFrames >= 3) {
+                c.outcome = { dom, settled: performance.now() };
+                armed = false;
+                return;
+              }
+            } else { stableFrames = 0; fingerprint = ''; }
+          }
+        } catch (error) { c.error = String(error); armed = false; return; }
+        actionFrame = requestAnimationFrame(check);
+      };
+      actionFrame = requestAnimationFrame(check);
+    },
+    disarm() { armed = false; cancelAnimationFrame(actionFrame); },
+    recordFrames(enabled) {
+      cancelAnimationFrame(gestureFrame);
+      if (!enabled) return;
+      c.frames = []; c.longTasks = []; c.inputs = [];
+      observer?.takeRecords(); actionStart = performance.now();
+      const tick = (time: number) => { c.frames.push(time); gestureFrame = requestAnimationFrame(tick); };
+      gestureFrame = requestAnimationFrame(tick);
+    },
+    flushTasks() { if (observer) collect(observer.takeRecords()); },
+  };
+  const collect = (entries: PerformanceEntry[]) => {
+    c.longTasks.push(...entries.filter(e => e.startTime + e.duration >= actionStart)
+      .map(e => ({ start: e.startTime, duration: e.duration })));
+  };
+  const observer = PerformanceObserver.supportedEntryTypes.includes('longtask')
+    ? new PerformanceObserver(list => collect(list.getEntries())) : null;
+  observer?.observe({ type: 'longtask' });
+  for (const type of ['click', 'pointerup']) window.addEventListener(type, event => {
+    if (armed && type === wantedEvent) c.inputs.push({ type, created: event.timeStamp, received: performance.now() });
+  }, { capture: true });
+}
diff --git a/tests/perf/harness/fixture.ts b/tests/perf/harness/fixture.ts
new file mode 100644
index 00000000..5197c585
--- /dev/null
+++ b/tests/perf/harness/fixture.ts
@@ -0,0 +1,82 @@
+import { spawn, type ChildProcess } from 'node:child_process';
+import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
+import { tmpdir } from 'node:os';
+import { createServer } from 'node:net';
+import path from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { seedMappingFixture } from '../../browser/support/browser-mapping-fixture.mjs';
+import { canvasSaveFixture } from '../../support/mappingDiagram';
+import { singleDiagramScene } from '../../../domain/core/diagrams/projectDiagramCanvas';
+import { RevisionedDiagramService } from '../../../domain/core/diagrams/diagramService';
+import { diagramContentNodes } from '../../../domain/core/diagrams/diagramContentNodes';
+import { defaultArrowAppearance, type DiagramConnection } from '../../../domain/core/diagrams/diagramConnection';
+
+const repo = fileURLToPath(new URL('../../../', import.meta.url));
+export type Seeded = Awaited<ReturnType<typeof resetFixture>>;
+
+async function stop(server?: ChildProcess) {
+  if (!server || server.exitCode !== null || server.signalCode !== null) return;
+  await new Promise<void>(resolve => {
+    const timer = setTimeout(() => server.kill('SIGKILL'), 5000);
+    server.once('exit', () => { clearTimeout(timer); resolve(); });
+    server.kill('SIGTERM');
+  });
+}
+
+export async function resetFixture(size: 'normal') {
+  const root = await mkdtemp(path.join(tmpdir(), `mapping-f02-${size}-`));
+  let server: ChildProcess | undefined;
+  const remove = async () => { try { await stop(server); } finally { await rm(root, { recursive: true, force: true }); } };
+  try {
+    await seedMappingFixture(root, { ascii: 'F02 fixture', nodes: [] });
+    const catalogPath = path.join(root, '.diagrams/representations/catalog.json');
+    const catalog = JSON.parse(await readFile(catalogPath, 'utf8'));
+    const scene = singleDiagramScene('F02 fixture');
+    const ids = ['d1', 'd2', 'd3', 'd4', 'd5', 'd6'];
+    const service = new RevisionedDiagramService();
+    scene.contents = Object.fromEntries(ids.map(id => [id, service.create({ id, revision: 0, structureKind: 'tree',
+      ascii: `${id.toUpperCase()}\n\n|-- ${id} branch\n|   \x60-- ${id} leaf\n\x60-- ${id} tail\n`,
+    }).diagram]));
+    if (scene.root.kind !== 'container') throw Error('Fixture requires a container root');
+    scene.root.children = ids.map((id, i) => ({ id, kind: 'diagram', contentId: id, collapsed: false,
+      position: { column: (i % 3) * 30, row: 5 + Math.floor(i / 3) * 22 } }));
+    const edges: DiagramConnection[] = ids.slice(0, -1).map((id, i) => ({ id: `${id}-${ids[i + 1]}`,
+      // Route the measured edge from the label's right side: automatic left-side
+      // proxy routing crosses the subtree toggle and intercepts an unfold click.
+      source: { kind: 'content-node', displayNodeId: `grid:${id}`, side: id === 'd3' ? 'right' : 'auto',
+        contentNodeId: diagramContentNodes(scene.contents[id].content).find(node => node.line === 4)!.id,
+        revisionId: scene.contents[id].content.revisionId },
+      target: { kind: 'box', displayNodeId: `grid:${ids[i + 1]}`, side: 'auto' },
+      appearance: { ...defaultArrowAppearance, label: `${id} to ${ids[i + 1]}` },
+    }));
+    catalog.revisions['revision-overview'].content = { kind: 'canvas-history',
+      history: canvasSaveFixture({ name: 'F02 fixture', scene, edges }).history };
+    await writeFile(catalogPath, JSON.stringify(catalog));
+    const port = await new Promise<number>((resolve, reject) => {
+      const socket = createServer();
+      socket.once('error', reject);
+      socket.listen(0, '127.0.0.1', () => {
+        const address = socket.address();
+        if (!address || typeof address === 'string') throw Error('Expected TCP address');
+        socket.close(error => error ? reject(error) : resolve(address.port));
+      });
+    });
+    const url = `http://127.0.0.1:${port}`;
+    let errors = '';
+    server = spawn(process.execPath, ['scripts/dev/start-server.mjs', 'preview', '--host', '127.0.0.1', '--port', String(port), '--strictPort'], {
+      cwd: repo, env: { ...process.env, NEW_DIAGRAM_PROJECT_ROOT: root,
+        NEW_DIAGRAMS_DIR: path.join(root, '.diagrams'), NEW_DIAGRAM_AGENT: 'fake' },
+      stdio: ['ignore', 'ignore', 'pipe'],
+    });
+    server.stderr!.on('data', chunk => { errors += chunk; });
+    server.on('error', error => { errors += String(error); });
+    const deadline = Date.now() + 30_000;
+    while (true) {
+      if ((await fetch(url, { signal: AbortSignal.timeout(1000) }).catch(() => null))?.ok) break;
+      if (Date.now() >= deadline || server.exitCode !== null) throw Error(`Fixture server unavailable: ${errors}`);
+      await new Promise(resolve => setTimeout(resolve, 100));
+    }
+    return { canvasUrl: `${url}/mapping?diagram=representation-overview`, remove,
+      description: { diagrams: ids.length, edges: edges.length, size } };
+  } catch (error) { await remove(); throw error; }
+}
diff --git a/tests/perf/harness/phases.ts b/tests/perf/harness/phases.ts
new file mode 100644
index 00000000..6ea41943
--- /dev/null
+++ b/tests/perf/harness/phases.ts
@@ -0,0 +1,30 @@
+import { appendFile, mkdir } from 'node:fs/promises';
+import { dirname } from 'node:path';
+
+export class PhaseRecorder {
+  lastCompleted: string | null = null;
+  constructor(private file: string, private metadata: { flow: string; test: string }) {}
+
+  async run<T>(phase: string, action: () => Promise<T>): Promise<T> {
+    await mkdir(dirname(this.file), { recursive: true });
+    const started = performance.now();
+    const startedAt = new Date().toISOString();
+    let error: unknown;
+    let succeeded = false;
+    try {
+      const result = await action();
+      this.lastCompleted = phase;
+      succeeded = true;
+      return result;
+    } catch (caught) {
+      error = caught;
+      throw caught;
+    } finally {
+      await appendFile(this.file, JSON.stringify({ ...this.metadata, phase, startedAt,
+        endedAt: new Date().toISOString(), durationMs: performance.now() - started,
+        status: succeeded ? 'passed' : 'failed',
+        ...(!succeeded ? { error: String(error) } : {}), lastCompletedPhase: this.lastCompleted,
+      }) + '\n');
+    }
+  }
+}
